    const displayAddress = posSettings.address || 'Ist Floor Rather Plaza Kangan\nJ&K-191202';
    const displayPhone = posSettings.phone || '9906495133/7006089744';
    const displayGstin = posSettings.gstin || '01BNIPB3099J1Z4';

    const addressLinesHtml = displayAddress.split('\n')
      .map(line => `<div class="center text-small">${line.trim()}</div>`)
      .join('');
    const contactLineHtml = displayPhone ? `<div class="center text-small">Contact No: ${displayPhone.trim()}</div>` : '';
    const gstinLineHtml = displayGstin ? `<div class="center text-small">GSTIN : ${displayGstin.trim()}</div>` : '';

    const headerFooterLines = `${addressLinesHtml}${contactLineHtml}${gstinLineHtml}`;

    let qrCodeHtml = '';
    if (posSettings.printUpiQr) {
      try {
        const payeeName = business?.business_name || business?.name || posSettings.receiptHeader || 'SHAHE TEHZEEB RESTAURANT';
        let upiUri = '';
        let displayUpiId = '';
        let brandLabel = '';

        if (posSettings.qrMode === 'static') {
          const activeEntry = (posSettings.staticUpiList || []).find(e => e.id === posSettings.activeStaticUpiId);
          if (activeEntry) {
            upiUri = `upi://pay?pa=${activeEntry.upiId}&pn=${encodeURIComponent(payeeName)}&cu=INR`;
